class Money {
public:
  Money& operator+=(const Money& r) {
    cents_ += r.cents_;
    return *this;
  }
  long cents() const { return cents_; }
private:
  long cents_;
};
Money operator+(Money l, const Money& r) {
  l += r; return l;
}

class Money {
  friend std::ostream& operator<<(
      std::ostream& os, const Money& m) {
    return os << (m.cents_/100) << "."
               << (m.cents_%100);
  }
private:
  long cents_;
};
